 id uuid PRIMARY KEY CHECK(substring(id::text,15,1)='7'),organisation_id uuid NOT NULL REFERENCES organisations(id),scope_kind text NOT NULL,scope_id uuid NOT NULL,property_id uuid,parent_id uuid,subject_id uuid,
 kind text NOT NULL,state text NOT NULL,title text NOT NULL CHECK(length(title) BETWEEN 3 AND 200),counterparty_reference text NOT NULL DEFAULT '' CHECK(length(counterparty_reference)<=300),external_reference text NOT NULL DEFAULT '' CHECK(length(external_reference)<=300),
 amount_minor bigint CHECK(amount_minor IS NULL OR amount_minor BETWEEN 0 AND 1000000000000000),currency text CHECK(currency IS NULL OR currency~'^[A-Z]{3}$'),starts_at timestamptz,ends_at timestamptz,
 attributes jsonb NOT NULL DEFAULT '{}' CHECK(jsonb_typeof(attributes)='object' AND octet_length(attributes::text)<=16384),evidence_refs jsonb NOT NULL DEFAULT '[]' CHECK(jsonb_typeof(evidence_refs)='array' AND jsonb_array_length(evidence_refs)<=50),
 approval_id uuid,assigned_to uuid REFERENCES business_accounts(id),last_actor_id uuid REFERENCES business_accounts(id),last_action text NOT NULL DEFAULT 'CREATED',closed_at timestamptz,
 version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid REFERENCES business_accounts(id),created_by_service text NOT NULL DEFAULT coalesce(nullif(current_setting('business.actor_service',true),''),''),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK(created_by IS NOT NULL OR created_by_service<>''),CHECK((amount_minor IS NULL)=(currency IS NULL)),FOREIGN KEY(organisation_id,approval_id) REFERENCES approval_requests(organisation_id,id),
 CHECK(kind IN ('MORTGAGE','PAYMENT_PLAN','INSTALMENT','BRIDGE')),CHECK(state IN ('REQUESTED','CONSENTED','SUBMITTED','APPROVED','DECLINED','WITHDRAWN')),CHECK(scope_kind='PROPERTY'),CHECK(property_id IS NOT NULL AND property_id=scope_id),CHECK(length(counterparty_reference)>=3),CHECK(amount_minor IS NOT NULL AND currency IS NOT NULL),FOREIGN KEY(organisation_id,property_id) REFERENCES properties(organisation_id,id),UNIQUE(organisation_id,id)
);
CREATE INDEX finance_offer_refs_scope ON finance_offer_refs(organisation_id,scope_id,state,created_at DESC,id);
CREATE TRIGGER finance_offer_refs_guard BEFORE UPDATE OR DELETE ON finance_offer_refs FOR EACH ROW EXECUTE FUNCTION business_ops_state_guard('REQUESTED>CONSENTED,CONSENTED>SUBMITTED,SUBMITTED>APPROVED,SUBMITTED>DECLINED,REQUESTED>WITHDRAWN,CONSENTED>WITHDRAWN,SUBMITTED>WITHDRAWN');

